		Resource:  a.key.Resource,
		Namespace: a.key.Namespace,
	}, folder)
	if err != nil && a.onCheckError != nil {
		a.onCheckError(err)
	}
	isAdmin := err == nil && resp.Allowed
	a.folderAdmin[folder] = isAdmin
	return isAdmin

